#![no_std]
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]

// use libc::posix::{printf, write, puts};
use core::ffi::c_char;
use core::fmt::{self, Write};
use cstr_core::CString;

// Pull in the bindings generated by build.rs
include!("./bindings.rs");

// unsafe extern "C" {
//     // Standard POSIX write. File descriptor 1 is stdout.
//     pub fn write(fd: i32, buf: *const c_void, count: usize) -> isize;
//     pub fn putchar(c: i32) -> i32;
// }

pub struct LibcConsole;

impl Write for LibcConsole {
    fn write_str(&mut self, s: &str) -> fmt::Result {
        // A 256-byte stack buffer. We leave 1 byte at the end for the null terminator.
        const BUF_LEN: usize = 256;
        let mut buf = [0u8; BUF_LEN];
        let mut i = 0;

        for byte in s.bytes() {
            buf[i] = byte;
            i += 1;

            // If the buffer fills up, flush it to the screen, then reset
            if i == BUF_LEN - 1 {
                buf[i] = 0; // Null terminate
                unsafe {
                    // Use printf/scr_printf.
                    // Note: puts() appends a newline automatically, which breaks chunking!
                    printf(buf.as_ptr() as *const c_char);
                    scr_printf(buf.as_ptr() as *const c_char);
                }
                i = 0;
            }
        }

        // Flush any remaining bytes
        if i > 0 {
            buf[i] = 0; // Null terminate
            unsafe {
                printf(buf.as_ptr() as *const c_char);
                scr_printf(buf.as_ptr() as *const c_char);
            }
        }

        Ok(())
    }
}

#[doc(hidden)]
pub fn _printdebug(args: core::fmt::Arguments) {
    let mut console = LibcConsole;
    let _ = console.write_fmt(args);
}

#[macro_export]
macro_rules! print {
    ($($arg:tt)*) => {
        $crate::_printdebug(core::format_args!($($arg)*));
    };
}

#[macro_export]
macro_rules! println {
    () => {
        $crate::print!("\r\n");
    };
    ($($arg:tt)*) => {
        $crate::_printdebug(core::format_args!($($arg)*));
        $crate::_printdebug(core::format_args!("\r\n"));
    };
}

